-- Adds the Vedic Sages book. Inserted inactive with no file: 0011 (generated by the upload tool) sets
-- pdf_url and active = true once the zip is uploaded. Re-running never touches pdf_url / active.
insert into public.catalog_items
  (id, type, title, subtitle, description, price_minor, currency, cover, pdf_url, tags, related_ids, route, requires_schedule, sort_order, active)
values
  ('book-vedic-sages', 'book', 'The Old Fart''s Guide to Vedic Sages', 'The Rishis, Sages and Masters of India — with the Mantras companion',
   'A pictorial journey through the great sages of India, from the Saptarishis and the seers of the Vedas to Patanjali, Shankara, Mahavatar Babaji and the masters we have only just lost. Includes the companion Old Fart''s Guide to Mantras, the sacred sounds the sages handed down.',
   2775, 'SGD', '/covers/book-vedic-sages.jpg', '', array['book','vedic'], array['book-vedic-gods','book-ayurveda'], '/books/vedic-sages', false, 13, false)
on conflict (id) do update set
  type = excluded.type, title = excluded.title, subtitle = excluded.subtitle, description = excluded.description,
  price_minor = excluded.price_minor, cover = excluded.cover,
  tags = excluded.tags, related_ids = excluded.related_ids, route = excluded.route,
  requires_schedule = excluded.requires_schedule, sort_order = excluded.sort_order;
